/// `action(L, y, path, x, a, b)`: substitutes `path` for `y` in Lagrangian `L`
/// and forms the definite action integral `defint(L[y:=path], x, a, b)`.
inline Term action(const Term &a0, const Term &a1, const Term &a2,
                   const Term &a3, const Term &a4, const Term &a5) {
  Term args[] = {a0, a1, a2, a3, a4, a5};
  return apply("action", args, 6);
}

/// `add(a, b, ...)` forms the sum of any number of terms and is printed with
/// `+`. Addition is associative and commutative. Numeric operands are added
/// directly. The empty sum is `0`.
template <class... Args> inline Term add(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("add", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("add", list, sizeof...(Args));
  }
}

