/// or truncated Taylor polynomial `sum_{k<=n} A^k / k!`.
template <class... Args> inline Term exp_map(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("exp_map", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("exp_map", list, sizeof...(Args));
  }
}

