/// Undirected graph constructor `graph(n, edges[, hyperedges])` with vertices
/// `0..n-1`, edge list `list(list(u, v[, w]), ...)`, and optional hyperedges.
template <class... Args> inline Term graph(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("graph", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("graph", list, sizeof...(Args));
  }
}

