/// `is_lie_algebra(basis[, coords])`: `true` if `span(basis)` is closed under
/// the Lie bracket and satisfies the Jacobi identity.
template <class... Args> inline Term is_lie_algebra(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("is_lie_algebra", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("is_lie_algebra", list, sizeof...(Args));
  }
}

