/// is not a power of two keeps its length: ```rust use num_complex::Complex;
/// use rssn::kernels::transforms::fft; let mut data = vec![Complex::new(1.0,
/// 0.0); 3]; fft(&mut data); assert_eq!(data.len(), 3); // [3, 0, 0] for a
/// constant signal. assert!((data[0].re - 3.0).abs() < 1e-12); ```
