/// one; the result is a `Value`, not a `Term`.
template <class... Args>
inline Value num_mcmc_metropolis_hastings(Args &&...args) {
  return detail::call_inferred("num_mcmc_metropolis_hastings",
                               std::forward<Args>(args)...);
}

