/// by [`minimize`].
inline Term num_optimizer_regression_problem(const Term &a0) {
  Term args[] = {a0};
  return apply("num_optimizer_regression_problem", args, 1);
}

/// Returns fitted minus observed responses in coherent response units. The
/// positive response reference attests the output dimension. Residual vector at
/// `beta`.
inline Term num_optimizer_regression_residuals(const Term &a0, const Term &a1,
                                               const Term &a2) {
  Term args[] = {a0, a1, a2};
  return apply("num_optimizer_regression_residuals", args, 3);
}

