template <class... Args> inline Term shear(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("shear", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("shear", list, sizeof...(Args));
  }
}

/// Constructs a 3x3 homogeneous 2D shear matrix from `(shx, shy)`.
inline Term shear_2d(const Term &a0, const Term &a1) {
  Term args[] = {a0, a1};
  return apply("shear_2d", args, 2);
}

/// Constructs a 4x4 homogeneous 3D shear matrix from 6 off-diagonal shear
/// factors.
inline Term shear_3d(const Term &a0, const Term &a1, const Term &a2,
                     const Term &a3, const Term &a4, const Term &a5) {
  Term args[] = {a0, a1, a2, a3, a4, a5};
  return apply("shear_3d", args, 6);
}

