template <class... Args> inline Term translation(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("translation", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("translation", list, sizeof...(Args));
  }
}

