/// `xor(p1, p2, ...)`: variadic exclusive-or (parity), true when an odd number
/// of operands are true.
template <class... Args> inline Term xor_op(Args &&...args) {
  if constexpr (sizeof...(Args) == 0) {
    return apply("xor", nullptr, 0);
  } else {
    Term list[] = {Term(std::forward<Args>(args))...};
    return apply("xor", list, sizeof...(Args));
  }
}

